## Why This Is Asked
This question tests understanding of cross-cache invalidation with multiple backends, race-condition handling, and production-grade guarantees.

## Key Concepts
- **Cross-cache invalidation**: Managing dependencies between caches (profile → timeline)
- **Dependency tracking**: Maintain a graph of cache keys affected by profile changes
- **Redis Streams**: Provides ordered, durable event delivery with at-least-once semantics
- **Idempotent retries**: Use correlation IDs to deduplicate processing
- **Bulk invalidations**: Batch multiple invalidations into single atomic operations

## Code Example
```javascript
// Publisher: emit profile update event
const event = { 
  type: 'PROFILE_UPDATED', 
  userId, 
  correlationId: uuid(), 
  timestamp: Date.now() 
};
await redis.xadd('cache_invalidation', '*', 'event', JSON.stringify(event));

// Consumer: process invalidation with idempotency
const processInvalidation = async (eventId, eventData) => {
  const { userId, correlationId } = JSON.parse(eventData);

  // Idempotency check
  const processed = await redis.set(`processed:${correlationId}`, '1', 'NX', 'EX', 86400);
  if (!processed) return; // Already processed

  // Invalidate profile cache
  await redis.del(`user:${userId}:profile`);

  // Invalidate dependent timeline caches
  const followers = await getFollowers(userId);
  const pipeline = redis.pipeline();
  for (const followerId of followers) {
    pipeline.del(`timeline:${followerId}`);
  }
  await pipeline.exec();

  // Acknowledge processing
  await redis.xack('cache_invalidation', 'invalidation_group', eventId);
};

// Consumer loop
while (true) {
  const result = await redis.xreadgroup(
    'GROUP', 'invalidation_group', 'consumer1',
    'BLOCK', 5000, 'STREAMS', 'cache_invalidation', '>'
  );
  if (result) {
    for (const [stream, events] of result) {
      for (const [eventId, fields] of events) {
        await processInvalidation(eventId, fields[1]);
      }
    }
  }
}
```

## Testing Strategy
1. **Unit tests**: Verify dependency resolution and invalidation order
2. **Integration tests**: Use testcontainers for Redis, verify at-least-once delivery
3. **Chaos testing**: Inject delays to verify idempotency under race conditions
4. **Bulk invalidation tests**: Verify batch operations handle thousands of keys efficiently

## Why This Is Asked
This question tests experience with cross-cache coherence, pub/sub-based invalidation, tombstone patterns, and stampede protection in production environments.

## Key Concepts
- Multi-layer cache invalidation with pub/sub synchronization
- Tombstones to prevent cache penetration during outages
- Per-key versioning for monotonic reads
- Handling partial outages and race conditions
- Read-path validation against primary version

## Code Example

```javascript
// Update path
async function updateProduct(id, data) {
  const newVersion = await redis.incr(`product:${id}:ver`);
  await redis.set(`product:${id}`, JSON.stringify({ ...data, version: newVersion }));
  await redis.publish('cache:invalidate', JSON.stringify({ key: `product:${id}`, version: newVersion }));
}

// Invalidation handler (runs on Memcached instances)
async function handleInvalidation(message) {
  const { key, version } = JSON.parse(message);
  await memcached.delete(key);
  await memcached.set(`${key}:tombstone`, version, { ttl: 300 });
}

// Read path with version validation
async function getProduct(id) {
  const [memcachedData, currentVersion] = await Promise.all([
    memcached.get(`product:${id}`),
    redis.get(`product:${id}:ver`)
  ]);

  if (memcachedData) {
    const cachedVersion = JSON.parse(memcachedData).version;
    if (cachedVersion === currentVersion) return JSON.parse(memcachedData);
  }

  const freshData = await redis.get(`product:${id}`);
  await memcached.set(`product:${id}`, freshData);
  return JSON.parse(freshData);
}
```

## Why This Is Asked
This tests practical ability to integrate REST, GraphQL, and gRPC behind a unified gateway, including automated OpenAPI generation and consistent authentication patterns.

## Key Concepts
- grpc-gateway for REST-to-gRPC translation
- OpenAPI generation from protobuf definitions
- JWT propagation through gRPC metadata
- Protocol buffer annotations for REST/GraphQL binding

## Code Example
```go
// REST to gRPC translation with grpc-gateway
func (s *server) CreateUser(ctx context.Context, req *pb.CreateUserRequest) (*pb.User, error) {
    // Forward to internal gRPC service
    return s.userService.CreateUser(ctx, req)
}

// Gateway setup with JWT propagation
func main() {
    mux := runtime.NewServeMux(
        runtime.WithIncomingHeaderMatcher(func(key string) (string, bool) {
            return key, strings.ToLower(key) == "authorization"
        }),
    )

    // Register gRPC services
    pb.RegisterUserServiceHandlerFromEndpoint(ctx, mux, "localhost:9090", []grpc.DialOption{
        grpc.WithInsecure(),
    })

    // GraphQL handler
    gqlHandler := handler.New(graphql.NewSchema())

    // Combine routers
    router := gin.Default()
    router.Any("/api/v1/*path", gin.WrapH(mux))
    router.POST("/graphql", gin.WrapH(gqlHandler))
}
```

## Why This Is Asked
Tests understanding of practical ES+CQRS integration across microservices with a lightweight saga.

## Key Concepts
- Event Sourcing: immutable event log
- CQRS: separate read model for queries
- Saga/Orchestrator: cross-service workflow with compensations

## Code Example
```javascript
// Minimal orchestrator sketch
function handleEvent(event) {
  switch (event.type) {
    case 'PostCreated':
      publish('ModerationRequested', { postId: event.data.postId });
      break;
    case 'ModerationResult':
      if (event.data.result === 'Approved') {
        publish('PostPublished', { postId: event.data.postId });
        publish('NotifyFollowers', { postId: event.data.postId });
      } else {
        publish('PostRejected', { postId: event.data.postId, reason: event.data.reason });
      }
      break;
  }
}
```

## Follow-up Questions
- How would you implement idempotent event processing in the Moderation service?
- What are the trade-offs of using a separate read model vs. a consolidated repository for listings of visible posts?

## Why This Is Asked
Tests practical understanding of cache invalidation patterns in a real, scalable backend with Redis/Memcached, focusing on data freshness, stampede prevention, and bulk invalidation across many keys.

## Key Concepts
- Cache-aside pattern
- Per-key locking to avoid stampede
- TTL vs explicit invalidation
- Bulk invalidation via pub/sub or background worker
- Data consistency in read-heavy workloads

## Code Example
```javascript
// Simplified cache-aside with per-user lock
async function getSummary(userId) {
  let cached = await redis.get(`sum:${userId}`);
  if (cached) return JSON.parse(cached);
  const lock = await redis.setNX(`lock:sum:${userId}`, '1');
  if (!lock) return await redis.get(`sum:${userId}`); // retry after data populated
  const fresh = await loadFromDB(userId);
  await redis.set(`sum:${userId}`, JSON.stringify(fresh), 'EX', 60);
  await redis.del(`lock:sum:${userId}`);
  return fresh;
}
```

## Follow-up Questions
- How would you adapt this for Redis clusters with replica lag?
- How would you test for race conditions and ensure stampede prevention in CI?
- How would you extend to multi-tenant invalidation and coordinate across shards?

## Why This Is Asked
This question evaluates your ability to design distributed workflows across microservices with CQRS/ES, ensuring tenant isolation, idempotency, and reliable message delivery.

## Key Concepts
- Long-running sagas with compensating transactions for rollback scenarios
- CQRS and Event Sourcing with versioned events for auditability and replay
- Outbox pattern ensuring at-least-once delivery
- Idempotency via correlationId and deduplication checks
- Per-tenant read models maintaining data isolation

## Code Example
```javascript
// Event-to-command mapping with deduplication
function handleEvent(evt, state) {
  if (state.processed?.includes(evt.id)) return;

  const cmd = mapEventToCommand(evt);
  enqueueToOutbox(cmd);
  state.processed = [...(state.processed || []), evt.id];
}

// Saga orchestration with compensation
async function executeOnboardSaga(tenantId, correlationId) {
  try {
    await TenantAuth.create(tenantId, correlationId);
    await Billing.setupQuota(tenantId, correlationId);
    await DataIngestion.provision(tenantId, correlationId);
    await Analytics.initialize(tenantId, correlationId);
  } catch (error) {
    await compensateSaga(tenantId, correlationId);
  }
}

async function compensateSaga(tenantId, correlationId) {
  await Analytics.deprovision(tenantId, correlationId);
  await DataIngestion.stop(tenantId, correlationId);
  await Billing.revertQuota(tenantId, correlationId);
  await TenantAuth.delete(tenantId, correlationId);
}
```

## Why This Is Asked
Tests understanding of cross-service orchestration, eventual consistency, and fault handling in microservices that use event sourcing and CQRS. It also probes patterns like outbox, idempotency, and compensating actions.

## Key Concepts
- Saga orchestration across multiple bounded contexts
- Event contracts and versioning for backward compatibility
- Outbox pattern for at-least-once delivery and durability
- Idempotent handlers keyed by correlationId
- Compensation actions to maintain consistency

## Code Example
```typescript
type Event = { type: string; payload: any; correlationId: string };
type Command = { type: string; payload: any; correlationId: string };

function handleEvent(e: Event) {
  const { type, payload, correlationId } = e;
  switch (type) {
    case 'CartCheckedOut':
      enqueue({ type: 'InventoryReserve', payload, correlationId });
      break;
    case 'InventoryReserved':
      enqueue({ type: 'PaymentCharge', payload, correlationId });
      break;
    case 'PaymentApproved':
      enqueue({ type: 'FinalizeOrder', payload, correlationId });
      break;
    case 'PaymentDeclined':
    case 'InventoryReserveFailed':
      enqueue({ type: 'CancelOrder', payload, correlationId });
      break;
  }
  // simple dedupe check
  if (alreadyProcessed(correlationId, type)) return;
  markProcessed(correlationId, type);
}
``` 

## Follow-up Questions
- How would you test idempotency guarantees across retries and outages?
- What metrics and tracing would you add to observe saga progress and failures?

## Why This Is Asked

This question probes practical orchestration with event-sourcing and CQRS in a realistic CMS workflow; tests ability to model compensating actions and simple idempotent handlers, not just theory.

## Key Concepts

- Saga orchestration across services
- Compensation patterns (undo, release)
- Event-sourcing store of domain events
- Read models for article status
- Idempotent event handlers and outbox pattern

## Code Example

```javascript
// Minimal orchestrator sketch
class SagaOrchestrator {
  constructor(store) { this.store = store }
  startSaga(id) { this.store.appendEvent(id, 'DraftCreated', {}) }
  onEvent(e) {
    switch(e.type){
      case 'LicenseReserved':
        this.store.appendEvent(e.id, 'PaymentRequested', {})
        break;
      case 'PaymentProcessed':
        this.store.appendEvent(e.id, 'PublishRequested', {})
        break;
      case 'PaymentFailed':
      case 'LicenseReservationFailed':
        this.compensate(e.id)
        break;
    }
  }
  compensate(id){
    this.store.appendEvent(id, 'CancelDraft', {})
  }
}
```

## Follow-up Questions

- How would you implement idempotency for repeated LicenseReserved events?
- How would you test the orchestration with replayed event streams?

## Why This Is Asked

Tests ability to design a policy-driven, multi-source token issuance flow with per-tenant constraints and real-time evaluation.

## Key Concepts

- Lightweight policy decision point (PDP) for token issuance
- Per-tenant audience/issuer metadata and key rotation
- Context-based access controls: IP allowlist, geolocation, time window, device fingerprint
- Caching decisions to reduce latency and load

## Code Example

```javascript
// issuance after policy approval (sketch)
function issueJWTForPolicyApproved(payload, tenant, kid, ttlSec) {
  const now = Math.floor(Date.now()/1000);
  const exp = now + ttlSec;
  const tokenPayload = {
    iss: `https://idp.example/${tenant}`,
    aud: `https://api.${tenant}.service`,
    sub: payload.sub,
    iat: now,
    exp,
    nonce: payload.nonce,
    tenant
  };
  return signJWT(tokenPayload, kid);
}
```

## Follow-up Questions

- How would you test policy changes without affecting production tokens?
- How would you model multi-tenant policy conflicts and roll back safely?

## Why This Is Asked
Assesses ability to design cross-protocol schema alignment and implement practical versioning strategies.

## Key Concepts
- Multi-protocol schema mapping from canonical model
- Unified internal service layer with protocol adapters
- Consistent versioning across all protocols
- Contract validation and routing patterns

## Code Example

```javascript
// Canonical model adapter
function toInternalBook(restInput) {
  return {
    id: restInput.id || generateId(),
    title: restInput.title,
    author: restInput.author,
    stock: restInput.stock || 0
  };
}

// Protocol-agnostic service layer
const bookService = {
  async getBook(id) {
    return await database.books.findById(id);
  },
  async createBook(bookData) {
    const internalBook = toInternalBook(bookData);
    return await database.books.create(internalBook);
  }
};

// Protocol adapters
const restAdapter = {
  getBook: async (req, res) => {
    const book = await bookService.getBook(req.params.id);
    res.json(book);
  },
  createBook: async (req, res) => {
    const book = await bookService.createBook(req.body);
    res.status(201).json(book);
  }
};

// GraphQL schema
type Book {
  id: ID!
  title: String!
  author: String!
  stock: Int!
}

type Query {
  getBook(id: ID!): Book
}

type Mutation {
  addBook(title: String!, author: String!, stock: Int): Book
}

// gRPC service definition
service BookService {
  rpc GetBook(GetBookRequest) returns (Book);
  rpc CreateBook(CreateBookRequest) returns (Book);
}

// Versioning patterns
// REST: /api/v1/books
// GraphQL: Use @deprecated directive for v2 changes
// gRPC: package v1.bookservice;
```

## Implementation Strategy
1. Define canonical domain model first
2. Create protocol-specific schemas that map to the canonical model
3. Implement adapter layer for request/response transformation
4. Build unified service layer with business logic
5. Apply consistent versioning strategy across all protocols
